  ('9b216e94-5f02-51fe-8e8a-09c9609ec28b', '5a073057-758e-56db-84d0-057dcab02c74', 5, 'skriv', 'Temperaturen är 3 °C och sjunker 7 grader. Hur många grader är det då?', null, '["-4","- 4"]'::jsonb, 'Tre grader ner till noll och fyra grader till: 3 − 7 = −4.'),
  ('afbcf904-d3a8-50ff-8212-fea1df980a9a', '5a073057-758e-56db-84d0-057dcab02c74', 6, 'skriv', 'Räkna: 5 − 8', null, '["-3","- 3"]'::jsonb, 'Fem steg ner till noll, och tre steg till under noll: −3.'),
