  ('dbef14f7-e39e-5ebd-aa32-faf44e1af0d0', '3b067982-5a46-5bf2-997e-6da0d85a1c8d', 4, 'skriv', 'Skriv motsatsen till ”dag”.', null, '["natt"]'::jsonb, 'På dagen är det ljust och på natten är det mörkt.'),
  ('fcbe1200-a178-59c5-9b9c-958a9ab5876a', '3b067982-5a46-5bf2-997e-6da0d85a1c8d', 5, 'skriv', 'Skriv motsatsen till ”ja”.', null, '["nej"]'::jsonb, 'Ja och nej är motsatser.'),
